const go=useCallback(p=>{if(recordingId){notify('Finish the take before leaving the recording room.','error');return}setPage(p);setStudioId('');setSearch('')},[recordingId,notify]);const activeSession=data?.sessions.find(s=>s.id===studioId);const refresh=useCallback(async()=>{let w=await api('/workspace');setData(w);return w},[]);
