const editSave=useCallback(async(kind,item)=>{if(item.id){let old=data[kind].find(x=>x.id===item.id);setData(d=>({...d,[kind]:d[kind].map(x=>x.id===item.id?{...x,...item}:x)}));try{let saved=await api(`/resources/${kind}/${item.id}`,{method:'PATCH',body:JSON.stringify(item)});setData(d=>({...d,[kind]:d[kind].map(x=>x.id===item.id?saved:x)}));notify('Saved. Nothing lost in the mix.');setModal(null)}catch(e){setData(d=>({...d,[kind]:d[kind].map(x=>x.id===item.id?old:x)}));throw e}}else await create(kind,item)},[data,create,notify]);
const remove=useCallback(async(kind,item)=>{if(kind==='sessions'&&recording.current&&data.tracks.some(t=>t.id===recording.current.trackId&&t.sessionId===item.id)){notify('Finish the take before deleting its session.','error');return}let snapshot;setData(d=>{snapshot=d;let next={...d,[kind]:d[kind].filter(x=>x.id!==item.id)};if(kind==='sessions'){next.tracks=d.tracks.filter(x=>x.sessionId!==item.id);next.exports=d.exports.filter(x=>x.sessionId!==item.id)}if(kind==='tracks'){const t=d.tracks.find(x=>x.id===item.id),s=d.sessions.find(x=>x.id===t?.sessionId);next.exports=d.exports.filter(x=>x.trackId!==item.id);if(s)next.sessions=d.sessions.map(x=>x.id===s.id?{...x,tracks:Math.max(0,(x.tracks||0)-1)}:x)}return next});setModal(null);if(kind==='sessions'&&studioId===item.id){setStudioId('');setPage('sessions')}try{await api(`/resources/${kind}/${item.id}`,{method:'DELETE'});notify('Removed from your studio.')}catch(e){setData(snapshot);notify(e.message,'error')}},[studioId,notify,recordingId,data]);
const askDelete=(kind,item)=>setModal({kind:'delete',resourceKind:kind,item});const openCreate=kind=>{if(kind==='tracks'&&!data.sessions.length){notify('Set up a session first, then make your first track.','error');setModal({kind:'editor',resourceKind:'sessions'});return}if(kind==='exports'&&!data.tracks.some(t=>t.recorded)){notify('Make or select a recorded track before preparing its export.');return}setModal({kind:'editor',resourceKind:kind})};
const createSession=useCallback(async form=>{let created=await create('sessions',{...form,date:new Date().toISOString().slice(0,10),duration:'00:00',tracks:0,format:`${depth}-bit / ${rate/1000} kHz`,status:form.status||'In progress',color:['orange','purple','green','blue'][Math.floor(Math.random()*4)]});for(let i=0;i<2;i++)await api('/resources/tracks',{method:'POST',body:JSON.stringify({name:i===0?'Input 1 · main':'Input 2 · room',sessionId:created.id,input:`Input ${i+1}`,gain:0,armed:i===0,muted:false,color:i===0?'orange':'blue'})});await refresh();return created},[create,refresh,rate,depth]);
const saveItem=async(kind,item)=>{if(kind==='sessions'&&!item.id)return createSession(item);if(kind==='tracks'&&!item.id&&data.sessions.find(s=>s.id===item.sessionId)?.tracks!==undefined){let updated={...item,armed:item.armed??true,color:item.color||'orange'};let t=await create('tracks',updated);let s=data.sessions.find(x=>x.id===t.sessionId);if(s)await patch('sessions',s.id,{tracks:data.tracks.filter(x=>x.sessionId===s.id).length+1},{immediate:true,silent:true});return t}if(kind==='exports'&&!item.id){const t=data.tracks.find(x=>x.id===item.trackId);if(!t?.recorded){throw new Error('Choose a recorded track for this export.')}return create('exports',{...item,name:item.name||`${t.name} — WAV master`,date:new Date().toISOString().slice(0,10),format:item.format||'WAV',status:'Ready',depth:item.depth||t.recordedDepth||depth,rate:item.rate||t.recordedRate||48000,size:`${t.duration||'WAV PCM'}`})}return editSave(kind,item)};
const openStudio=id=>{if(recordingId&&id!==studioId){notify('Finish this take before opening another session.','error');return}setStudioId(id);setPage('studio');setSearch('')};
